const removeUserFromSpaceGroups = `-- name: RemoveUserFromSpaceGroups :exec
DELETE FROM group_members gm
USING groups g
WHERE gm.group_id = g.id
  AND g.space_id = $1
  AND gm.user_id = $2
`

type RemoveUserFromSpaceGroupsParams struct {
	SpaceID pgtype.UUID `json:"space_id"`
	UserID  pgtype.UUID `json:"user_id"`
}

// Removing someone from a space must drop them from every group in it.
// group_members references users, not spaces, so there is no cascade to rely
// on: without this the person keeps live access through their old groups.
func (q *Queries) RemoveUserFromSpaceGroups(ctx context.Context, arg RemoveUserFromSpaceGroupsParams) error {
	_, err := q.db.Exec(ctx, removeUserFromSpaceGroups, arg.SpaceID, arg.UserID)
	return err
}

