const upsertGroupGrant = `-- name: UpsertGroupGrant :one

INSERT INTO shares (node_id, kind, level, can_download, can_share, grantee_group_id, created_by)
VALUES ($1, 'group', $2, $3, $4, $5, $6)
ON CONFLICT (node_id, grantee_group_id) WHERE kind = 'group'
DO UPDATE SET level = EXCLUDED.level, can_download = EXCLUDED.can_download,
              can_share = EXCLUDED.can_share, created_by = EXCLUDED.created_by
RETURNING id, tenant_id, node_id, kind, token_hash, grantee_user_id, grantee_group_id, level, can_download, can_share, expires_at, created_by, created_at, is_external
`

type UpsertGroupGrantParams struct {
	NodeID         pgtype.UUID `json:"node_id"`
	Level          ShareLevel  `json:"level"`
	CanDownload    bool        `json:"can_download"`
	CanShare       bool        `json:"can_share"`
	GranteeGroupID pgtype.UUID `json:"grantee_group_id"`
	CreatedBy      pgtype.UUID `json:"created_by"`
}

// ----------------------------------------------------------------- grants ---
// shares_group_uniq makes re-granting an update rather than a second row.
func (q *Queries) UpsertGroupGrant(ctx context.Context, arg UpsertGroupGrantParams) (Share, error) {
	row := q.db.QueryRow(ctx, upsertGroupGrant,
		arg.NodeID,
		arg.Level,
		arg.CanDownload,
		arg.CanShare,
		arg.GranteeGroupID,
		arg.CreatedBy,
	)
	var i Share
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.NodeID,
		&i.Kind,
		&i.TokenHash,
		&i.GranteeUserID,
		&i.GranteeGroupID,
		&i.Level,
		&i.CanDownload,
		&i.CanShare,
		&i.ExpiresAt,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.IsExternal,
	)
	return i, err
}
